#include <bits/stdc++.h>

using namespace std;
const int MOD = 998244353;
int main() {
    int t;
    scanf("%d", & t);
    while (t--) {
        int n;
        scanf("%d", & n);
        vector < vector < int >> g(n + 2);
        for (int i = 1; i <= n; i++) {
            int v;
            scanf("%d", & v);
            g[v].push_back(i);
        }
        vector < int > dp(n + 2, 0), nd(n + 2);
        vector < char > aL(n + 2), aR(n + 2);
        dp[0] = 1;
        long long ans = 0;
        for (int w = 1; w <= n; w++) {
            for (int x = 0; x < w; x++) aL[x] = aR[x] = 1;
            for (int i: g[w]) {
                int H = (i + 1) / 2, S = (n - i + 2) / 2;
                int tL = n - i / 2, tR = i + S - 1;
                for (int x = 0; x < w; x++) {
                    bool l = false, r = false;
                    if (w < tL) {
                        if (x == H - 1) l = true;
                    }
                    else if (w == tL) {
                        if (x <= H - 1) l = r = true;
                    }
                    if (w < tR) {
                        if (x == w - S) r = true;
                    }
                    else if (w == tR) {
                        if (x >= i - 1) l = r = true;
                    }
                    aL[x] &= l;
                    aR[x] &= r;
                }
            }
            if (w == n) {
                for (int x = 0; x < w; x++)
                    if (aL[x]) ans += dp[x];
                ans %= MOD;
                break;
            }
            for (int x = 0; x <= w; x++) nd[x] = 0;
            for (int x = 0; x < w; x++) {
                if (!dp[x]) continue;
                if (aL[x]) {
                    nd[x + 1] += dp[x];
                    if (nd[x + 1] >= MOD) nd[x + 1] -= MOD;
                }
                if (aR[x]) {
                    nd[x] += dp[x];
                    if (nd[x] >= MOD) nd[x] -= MOD;
                }
            }
            swap(dp, nd);
        }
        printf("%lld\n", ans);
    }
}
